function UIActionTeamInvitePopupDialog:InitData()
    self._typeData = {}

    -- 参数表控制各个页签是否显示
    local pages = self._comp:GetInvitePages()
    local tabStatusList = parse_strings(pages, ";")
    local tabNum = table.count(tabStatusList)

    for i = 2, 2 + tabNum do
        local open = checkNumber(tabStatusList[i-1]) == 1
        if open then
            local type, text = self:GetTypeInfo(i)
            table.insert(self._typeData, {
                selectImgPath = self:GetImgPath(type),
                showNormalBg = true,
                type = type,
                text = text,
                func = function()
                    self._curSelectInd = i
                    self._curSelectType = type
                    self:FillListInfo()
                end
            })
        end
    end
end

function UIActionTeamInvitePopupDialog:GetImgPath(type)
    if type == InviteType.World then
        return "UIAtlas/ActionTeamInvite/vit_icon_diamon_world.png"
    elseif type == InviteType.Friend then
        return "UIAtlas/ActionTeamInvite/vit_icon_diamon_friends.png"
    elseif type == InviteType.AiFriend then
        return "UIAtlas/ActionTeamInvite/vit_icon_diamon_friendsai.png"
    elseif type == InviteType.AiWorld then
        return "UIAtlas/ActionTeamInvite/vit_icon_diamon_ai.png"
    end
end

function UIActionTeamInvitePopupDialog:FillSelf(toggleIndex)
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, "Game.Behaviours.CommonTabToggleUp")
    if isNull(scr) then
        return
    end

    scr:FillToggles(self._typeData)

    scr:SetSelectState(toggleIndex, true)

    self:FillRealtimeRewardTips()
end

--- 实时组队奖励
function UIActionTeamInvitePopupDialog:FillRealtimeRewardTips()
    KTool.SetActive(self.TipsGroup, false)

    local houseInfo = RegionQuestMgr:GetInstance():GetHouseInfo()
    local questId = checkNumber(houseInfo.questId)
    local vo = RewardConfMgr:GetInstance():GetQuestRewardVo(questId)
    if isNull(vo) then
        return
    end

    local rewardIdList = vo.playerRewardItem
    local rewardNumList = vo.playerRewardNum

    if isNull(rewardIdList) or isNull(rewardNumList) then
        return
    end
    local rewards = parse_rewards(rewardIdList, rewardNumList, ";")

    if table.count(rewards) <= 0 then
        return
    end

    local reward = rewards[1]
    local rewardId = reward.goodsId
    local rewardNum = reward.goodsNum

    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(rewardId)
    if isNull(goodsVo) then
        printError("id %s 找不到道具信息", rewardId)
        return
    end

    KTool.SetActive(self.TipsGroup, true)
    CfUtils.FillText(self.TxtState2, string.format("%s X%d", goodsVo.name, rewardNum))
end

function UIActionTeamInvitePopupDialog:FillListInfo()
    CfUtils.SetActive(self.BtnFresh, self._curSelectType == InviteType.World)
    RegionQuestMgr:GetInstance():OverseaRegionalBossInvitePanelReq(self._curSelectType, function(data)
        self._allRole = checkTable(data.data)
        -- print("[支援]", table.dump(self._allRole, nil, 3))
        if self._curSelectType == InviteType.Friend then
            -- 把在线的好友排在前面
            self:AheadOnlineFriend(self._allRole)
        elseif self._curSelectType == InviteType.AiOfficial then
            -- 给AI重命名
            self:OfficialAIRename(self._allRole)
        elseif self._curSelectType == InviteType.AiFriend
        or self._curSelectType == InviteType.AiClub then
            -- 按战力排序
            self:SortByPower(self._allRole)
            -- 没有次数的好友置底
            self:DownNoTimesFriend(self._allRole)
        end
        if self._isInitLoopList then
            GameUtils.ReloadData(self.ScrollView, table.count(self._allRole))
        else
            self.ScrollView:InitListView(table.count(self._allRole), Bind(self, self.OnRefreshIndex))
            self._isInitLoopList = true
        end
        KTool.SetActive(self.RT_EmptyNode, table.count(self._allRole) <= 0)
    end)
end

function UIActionTeamInvitePopupDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self._allRole[index + 1]
    local go = cell.gameObject
    
    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.ActionTeamInvitePopup.UIActionTeamInvitePopupNode")
    if scr then
        scr:Refresh(data, self._curSelectType, function()
            local houseInfo = RegionQuestMgr:GetInstance():GetHouseInfo()
            local t = {
                panelType = self._curSelectType,
                invitedPlayerId = data.playerInfo.playerId,
                questId = checkNumber(houseInfo.questId)
            }
            self._curRoleInd = index + 1
            RegionQuestMgr:GetInstance():InvitePlayerReq(t)

            --好友的时候刷新个倒计时 不会计时关闭
            if self._curSelectType == InviteType.Friend then
                UIRaycastBlocker:RemoveCondition("InvitePlayerReq")
                self._allRole[self._curRoleInd].remainTime = 3
                scr:RefreshRemainTime(self._allRole[self._curRoleInd].remainTime)
            end
        end, self._comp)
    end

    return cell
end

function UIActionTeamInvitePopupDialog:GetTypeInfo(type)
    if type == InviteType.World then
        return InviteType.World, localize("搜索")
    elseif type == InviteType.Friend then
        return InviteType.Friend, localize("好友")
    elseif type == InviteType.AiFriend then
        return InviteType.AiFriend, localize("好友AI")
    elseif type == InviteType.AiWorld then
        return InviteType.AiWorld, localize("玩家AI")
    elseif type == InviteType.AiOfficial then
        return InviteType.AiOfficial, localize("官方AI")
    elseif type == InviteType.AiClub then
        return InviteType.AiClub, localize("社团AI")
    end
    return type, localize("新页签")
end

function UIActionTeamInvitePopupDialog:AheadOnlineFriend(friendList)
    table.inPlaceBubbleSort(friendList,function(a, b)
        return checkNumber(a.isOnline) >= checkNumber(b.isOnline)
    end)
end

function UIActionTeamInvitePopupDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self._comp = self.controller.Argument.parameters.comp
        self:InitData()

        self._curSelectInd = self.controller.Argument.parameters.selectIndex

        self:FillSelf(self._curSelectInd)
    end))
    return coWait
end

function UIActionTeamInvitePopupDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.RegionTeamInviteResult, self.EventRegionTeamInviteResult)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIActionTeamInvitePopupDialog:OfficialAIRename(roles)
    for i, v in ipairs(roles) do
        v.playerInfo.name = localize("官方AI _index_",{_index_ = i})
    end
end

--- 把没有邀请次数的好友置底
---@param friendList any
function UIActionTeamInvitePopupDialog:DownNoTimesFriend(friendList)
    table.inPlaceBubbleSort(friendList,function(a, b)
        local aHasTimes = checkNumber(a.remainInviteTimes) > 0 and 1 or 0
        local bHasTimes = checkNumber(b.remainInviteTimes) > 0 and 1 or 0
        return aHasTimes >= bHasTimes
    end)
end

function UIActionTeamInvitePopupDialog:SortByPower(friendList)
    table.sort(friendList, function(a, b)
        local powerA = checkNumber(a.combatVal)
        local powerB = checkNumber(b.combatVal)
        return powerA > powerB
    end)
end

return UIActionTeamInvitePopupDialog
